          <Routes>
            <Route path="/" element={<IssuesPage />} />
            <Route path="/issues/:id" element={<IssueDetailPage />} />
          </Routes>
        </AppLayout>
      </BrowserRouter>
    </QueryClientProvider>
  );
}

export default App;

